schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/growth-loops.json",
  "title": "Growth Loops spec",
  "type": "object",
  "required": ["loop_name", "loop_type", "input_source", "secondary_loops", "stages", "stage_metrics", "efficiency", "projection", "friction_map", "cac_payback", "quality_guardrail"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "event_name": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "loop_type": {"type": "string", "enum": ["viral", "ugc_search", "paid", "network_effect", "supply_side"]},
    "transition": {"type": "string", "enum": ["input-action", "action-output", "output-fuel_back"]},
    "stage": {
      "type": "object",
      "required": ["name", "event", "unit"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 3},
        "event": {"$ref": "#/definitions/event_name"},
        "unit": {"type": "string", "minLength": 3}
      }
    },
    "payback": {
      "type": "object",
      "required": ["blended_cac", "payback_months"],
      "additionalProperties": false,
      "properties": {
        "blended_cac": {"type": "number", "minimum": 0},
        "payback_months": {"type": "number", "minimum": 0}
      }
    }
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "loop_name": {"type": "string", "minLength": 3},
    "loop_type": {"$ref": "#/definitions/loop_type"},
    "input_source": {"type": "string", "enum": ["user_action", "content", "capital", "supply"]},
    "secondary_loops": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["type", "note"],
        "additionalProperties": false,
        "properties": {
          "type": {"$ref": "#/definitions/loop_type"},
          "note": {"type": "string", "minLength": 10}
        }
      }
    },
    "stages": {
      "type": "object",
      "required": ["input", "action", "output", "fuel_back"],
      "additionalProperties": false,
      "properties": {
        "input": {"$ref": "#/definitions/stage"},
        "action": {"$ref": "#/definitions/stage"},
        "output": {"$ref": "#/definitions/stage"},
        "fuel_back": {"$ref": "#/definitions/stage"}
      }
    },
    "stage_metrics": {
      "type": "array",
      "minItems": 3,
      "maxItems": 3,
      "items": {
        "type": "object",
        "required": ["transition", "event", "numerator", "denominator", "value", "basis", "measured_on", "sample_size"],
        "additionalProperties": false,
        "properties": {
          "transition": {"$ref": "#/definitions/transition"},
          "event": {"$ref": "#/definitions/event_name"},
          "numerator": {"type": "string", "minLength": 5},
          "denominator": {"type": "string", "minLength": 5},
          "value": {"type": "number", "minimum": 0},
          "basis": {"type": "string", "enum": ["measured", "assumption"]},
          "measured_on": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]},
          "sample_size": {"type": ["integer", "null"], "minimum": 1}
        },
        "if": {"properties": {"basis": {"const": "measured"}}},
        "then": {"properties": {"measured_on": {"type": "string"}, "sample_size": {"type": "integer"}}}
      }
    },
    "efficiency": {
      "type": "object",
      "required": ["k", "cycle_time_days", "reading", "multiplier", "growth_rate_per_cycle"],
      "additionalProperties": false,
      "properties": {
        "k": {"type": "number", "minimum": 0},
        "cycle_time_days": {"type": "number", "exclusiveMinimum": 0},
        "reading": {"type": "string", "enum": ["amplifier", "self_sustaining"]},
        "multiplier": {"type": ["number", "null"], "minimum": 1},
        "growth_rate_per_cycle": {"type": ["number", "null"], "minimum": 0}
      },
      "if": {"properties": {"k": {"exclusiveMaximum": 1}}},
      "then": {"properties": {"reading": {"const": "amplifier"}, "multiplier": {"type": "number"}, "growth_rate_per_cycle": {"type": "null"}}},
      "else": {"properties": {"reading": {"const": "self_sustaining"}, "multiplier": {"type": "null"}, "growth_rate_per_cycle": {"type": "number"}}}
    },
    "projection": {
      "type": "object",
      "required": ["horizon_days", "cycles", "decay", "rests_on_assumption", "headline", "cohorts"],
      "additionalProperties": false,
      "properties": {
        "horizon_days": {"type": "integer", "minimum": 90},
        "cycles": {"type": "integer", "minimum": 3},
        "decay": {
          "type": "object",
          "required": ["kind", "rate_per_cycle"],
          "additionalProperties": false,
          "properties": {
            "kind": {"type": "string", "enum": ["contributor_churn", "content_decay", "audience_saturation", "rising_cpm"]},
            "rate_per_cycle": {"type": "number", "exclusiveMinimum": 0, "maximum": 1}
          }
        },
        "rests_on_assumption": {"type": "boolean"},
        "headline": {"type": "string", "minLength": 20},
        "cohorts": {
          "type": "array",
          "minItems": 3,
          "items": {
            "type": "object",
            "required": ["cycle", "external_inputs", "loop_inputs", "total_inputs"],
            "additionalProperties": false,
            "properties": {
              "cycle": {"type": "integer", "minimum": 1},
              "external_inputs": {"type": "integer", "minimum": 0},
              "loop_inputs": {"type": "integer", "minimum": 0},
              "total_inputs": {"type": "integer", "minimum": 0}
            }
          }
        }
      }
    },
    "friction_map": {
      "type": "object",
      "required": ["bottleneck_stage", "bottleneck_value", "k_if_doubled", "experiments"],
      "additionalProperties": false,
      "properties": {
        "bottleneck_stage": {"$ref": "#/definitions/transition"},
        "bottleneck_value": {"type": "number", "minimum": 0},
        "k_if_doubled": {"type": "number", "minimum": 0},
        "experiments": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["rank", "name", "stage", "justification"],
            "additionalProperties": false,
            "properties": {
              "rank": {"type": "integer", "minimum": 1},
              "name": {"type": "string", "minLength": 5},
              "stage": {"$ref": "#/definitions/transition"},
              "justification": {"type": ["string", "null"], "minLength": 15}
            }
          }
        }
      }
    },
    "cac_payback": {
      "type": "object",
      "required": ["period_days", "attributed_by", "without_loop", "with_loop"],
      "additionalProperties": false,
      "properties": {
        "period_days": {"type": "integer", "minimum": 30},
        "attributed_by": {"$ref": "#/definitions/event_name"},
        "without_loop": {"$ref": "#/definitions/payback"},
        "with_loop": {"$ref": "#/definitions/payback"}
      }
    },
    "quality_guardrail": {
      "type": "object",
      "required": ["metric", "threshold", "loop_cohort_value", "baseline_value", "status"],
      "additionalProperties": false,
      "properties": {
        "metric": {"type": "string", "enum": ["activation_rate", "d30_retention", "indexed_and_trafficked_share"]},
        "threshold": {"type": "number", "minimum": 0, "maximum": 1},
        "loop_cohort_value": {"type": "number", "minimum": 0, "maximum": 1},
        "baseline_value": {"type": ["number", "null"], "minimum": 0, "maximum": 1},
        "status": {"type": "string", "enum": ["within", "breached"]}
      }
    }
  }
}

output-contract.example:
{
  "loop_name": "external document share loop",
  "loop_type": "viral",
  "input_source": "user_action",
  "secondary_loops": [
    {"type": "ugc_search", "note": "public templates indexed by search; tracked separately, not in this projection"}
  ],
  "stages": {
    "input": {"name": "new workspace signup", "event": "signup_completed", "unit": "new signups"},
    "action": {"name": "user shares a document with an external recipient", "event": "share_sent", "unit": "shares sent"},
    "output": {"name": "external recipient opens the shared document", "event": "share_viewed", "unit": "recipient views"},
    "fuel_back": {"name": "recipient signs up from the shared document", "event": "signup_via_share", "unit": "new signups"}
  },
  "stage_metrics": [
    {"transition": "input-action", "event": "share_sent", "numerator": "signups that sent at least one external share within 14 days", "denominator": "signups in the cohort", "value": 0.45, "basis": "measured", "measured_on": "2026-05-04", "sample_size": 8400},
    {"transition": "action-output", "event": "share_viewed", "numerator": "distinct external recipients who viewed", "denominator": "sharers", "value": 2.4, "basis": "measured", "measured_on": "2026-05-04", "sample_size": 3780},
    {"transition": "output-fuel_back", "event": "signup_via_share", "numerator": "viewers who signed up within 14 days", "denominator": "distinct viewers", "value": 0.12, "basis": "measured", "measured_on": "2026-05-04", "sample_size": 9072}
  ],
  "efficiency": {
    "k": 0.13,
    "cycle_time_days": 9,
    "reading": "amplifier",
    "multiplier": 1.15,
    "growth_rate_per_cycle": null
  },
  "projection": {
    "horizon_days": 120,
    "cycles": 13,
    "decay": {"kind": "audience_saturation", "rate_per_cycle": 0.05},
    "rests_on_assumption": false,
    "headline": "The loop adds about 13 percent on top of external signups and saturates toward 1,120 signups per 9-day cycle at 1,000 external inputs.",
    "cohorts": [
      {"cycle": 1, "external_inputs": 1000, "loop_inputs": 0, "total_inputs": 1000},
      {"cycle": 2, "external_inputs": 1000, "loop_inputs": 124, "total_inputs": 1124},
      {"cycle": 3, "external_inputs": 1000, "loop_inputs": 132, "total_inputs": 1132},
      {"cycle": 4, "external_inputs": 1000, "loop_inputs": 126, "total_inputs": 1126}
    ]
  },
  "friction_map": {
    "bottleneck_stage": "output-fuel_back",
    "bottleneck_value": 0.12,
    "k_if_doubled": 0.26,
    "experiments": [
      {"rank": 1, "name": "signup call to action on the shared-document view page", "stage": "output-fuel_back", "justification": null},
      {"rank": 2, "name": "prompt to share at first document completion", "stage": "input-action", "justification": "the view page redesign is blocked on the design system release for two weeks; this experiment is already built"}
    ]
  },
  "cac_payback": {
    "period_days": 90,
    "attributed_by": "signup_via_share",
    "without_loop": {"blended_cac": 310, "payback_months": 14.2},
    "with_loop": {"blended_cac": 271, "payback_months": 12.4}
  },
  "quality_guardrail": {
    "metric": "d30_retention",
    "threshold": 0.3,
    "loop_cohort_value": 0.33,
    "baseline_value": 0.34,
    "status": "within"
  }
}

{
  "loop_name": "growth flywheel",
  "loop_type": "viral and content",
  "input_source": "user_action",
  "secondary_loops": [],
  "stages": {
    "input": {"name": "new workspace signup", "event": "signup_completed", "unit": "new signups"},
    "action": {"name": "user shares a document", "event": "share_sent", "unit": "shares sent"},
    "output": {"name": "recipient opens the document", "event": "share_viewed", "unit": "recipient views"},
    "fuel_back": {"name": "retained user comes back", "event": "session_started", "unit": "sessions"}
  },
  "stage_metrics": [
    {"transition": "input-action", "event": "share_sent", "numerator": "signups that shared", "denominator": "signups in the cohort", "value": 0.3, "basis": "benchmark", "measured_on": null, "sample_size": null},
    {"transition": "action-output", "event": "share_viewed", "numerator": "recipients who viewed", "denominator": "sharers", "value": 2.4, "basis": "measured", "measured_on": null, "sample_size": null},
    {"transition": "output-fuel_back", "event": "session_started", "numerator": "viewers who signed up", "denominator": "distinct viewers", "value": 0.12, "basis": "measured", "measured_on": "2026-05-04", "sample_size": 9072}
  ],
  "efficiency": {
    "k": 0.6,
    "cycle_time_days": 9,
    "reading": "self_sustaining",
    "multiplier": null,
    "growth_rate_per_cycle": null
  },
  "projection": {
    "horizon_days": 30,
    "cycles": 1,
    "decay": {"kind": "none", "rate_per_cycle": 0},
    "rests_on_assumption": false,
    "headline": "Viral growth: signups double every month.",
    "cohorts": [
      {"cycle": 1, "external_inputs": 1000, "loop_inputs": 300, "total_inputs": 1300}
    ]
  },
  "friction_map": {
    "bottleneck_stage": "input-action",
    "bottleneck_value": 0.3,
    "k_if_doubled": 1.2,
    "experiments": []
  },
  "cac_payback": {
    "period_days": 90,
    "attributed_by": "organic",
    "without_loop": {"blended_cac": 310, "payback_months": 14.2},
    "with_loop": {"blended_cac": 180, "payback_months": 8}
  },
  "quality_guardrail": {
    "metric": "d30_retention",
    "threshold": 0.3,
    "loop_cohort_value": 0.19,
    "baseline_value": 0.34,
    "status": "within"
  }
}
